// A transparent exploratory matching tool, not an aptitude assessment.
const domains=[
{id:'ai',name:'AI·데이터·디지털 서비스',icon:'01',flow:'AI가 문서·코드·분석을 돕고 여러 업무를 연결합니다.',life:'학습·업무·서비스의 개인화와 자동화',subjects:['수학','정보','영어'],activities:['만들기','분석하기','문제 해결'],majors:'컴퓨터·소프트웨어·통계·AI',jobs:['소프트웨어 개발자','데이터 분석가','AI 응용 엔지니어'],work:'사용자 문제를 프로그램과 데이터로 해결하고, 결과의 정확도와 한계를 확인합니다.',prep:'함수·확률통계, Python 기초, 데이터 정리, 영어 자료 읽기',task:'공개 데이터로 질문 하나를 분석하거나 작은 자동화 기능 만들기',risk:'초급 구현·반복 분석도 자동화됩니다. 문제 정의와 실제 검증을 함께 배우세요.'},
{id:'robots',name:'로봇·기기·자동화',icon:'02',flow:'AI가 센서·기계와 결합해 물리 세계에서 행동하는 연구가 확대됩니다.',life:'제조·물류·농업·가정의 일부 작업 자동화',subjects:['수학','물리','정보'],activities:['만들기','손으로 실습','문제 해결'],majors:'전자·전기·기계·제어·메카트로닉스',jobs:['로봇·제어 엔지니어','임베디드 개발자','자동화 시스템 엔지니어'],work:'센서·모터·프로그램을 연결하고 성능·고장·안전을 시험합니다.',prep:'전기·힘·열, 수학 기초, 프로그래밍, 실험 기록',task:'지도하에 저전압 센서 실습 또는 자동화 구조 모형 제작',risk:'안전·비용·현장 적응이 도입 속도를 좌우합니다. 실제 장비 업무 선호도 확인하세요.'},
{id:'health',name:'건강·의료·바이오',icon:'03',flow:'AI가 연구·기록·영상 분석을 지원하며 생명과학과 실험 자동화에 연결됩니다.',life:'진료 준비·건강 기록 관리·연구 방법 변화',subjects:['생명과학','화학','수학','영어'],activities:['연구하기','사람 돕기','분석하기'],majors:'생명과학·생명공학·의공학·간호·보건·의학 등',jobs:['바이오 연구원','의료기기 개발·검증 전문가','간호·보건 전문직'],work:'생체 원리나 의료기술을 연구·검증하고, 전문 자격에 따라 사람의 건강을 지원합니다.',prep:'생명·화학 기초, 통계, 논문·자료 읽기, 소통과 윤리',task:'공공 보건 자료의 그래프를 해석하거나 의료기기 원리 조사',risk:'의료 직종은 서로 다른 면허·교육 경로가 필요합니다. AI 보조와 임상 판단을 구분하세요.'},
{id:'energy',name:'에너지·기후·환경',icon:'04',flow:'전력·자원 수요와 환경 문제가 기술·정책·사업의 선택을 함께 요구합니다.',life:'에너지 사용·건물 운영·자원 순환 방식 변화',subjects:['물리','화학','지구과학','수학','사회·경제'],activities:['분석하기','연구하기','사회 문제 해결'],majors:'전기·에너지·환경·화학공학·지구환경',jobs:['전력·에너지 엔지니어','환경·자원 분석 전문가','에너지 효율·운영 전문가'],work:'전력·자원 사용을 측정하고 기술·비용·환경 영향을 비교해 개선합니다.',prep:'전기·에너지·화학 원리, 수학·통계, 경제·정책 이해',task:'가정·학교의 에너지 사용을 공개 자료와 함께 분석',risk:'정책·산업 경기와 자원 비용의 영향을 받습니다. 기술만으로 모든 문제를 해결하지는 못합니다.'},
{id:'security',name:'보안·신뢰·안전',icon:'05',flow:'AI와 연결 서비스가 늘며 정보·시스템·제품의 신뢰성 확인이 중요해집니다.',life:'계정·개인정보·콘텐츠 진위·기기 안전 관리',subjects:['정보','수학','국어','사회·경제'],activities:['문제 해결','분석하기','사회 문제 해결'],majors:'정보보호·컴퓨터·전자·산업·안전 관련',jobs:['사이버보안 전문가','시험·신뢰성 엔지니어','개인정보·기술 위험 관리 전문가'],work:'취약점과 실패 조건을 분석하고 보안·검증·운영 절차를 개선합니다.',prep:'운영체제·네트워크 기초, 통계, 정확한 글쓰기, 윤리',task:'본인 계정·기기 권한을 점검하거나 공개 정보의 출처 검증',risk:'진단·검증 도구도 자동화됩니다. 허가된 환경에서 실습하고 원리를 배우세요.'},
{id:'creative',name:'디자인·미디어·공간 경험',icon:'06',flow:'AI가 이미지·영상·3차원 콘텐츠의 제작과 개인화를 바꿉니다.',life:'게임·광고·가상공간·제품 사용 경험 변화',subjects:['미술·디자인','국어','정보','영어'],activities:['표현하기','만들기','사람 이해'],majors:'디자인·미디어·콘텐츠·컴퓨터·건축 관련',jobs:['UX·제품 디자이너','콘텐츠 기획·제작자','3D·실감 콘텐츠 개발자'],work:'사용자 경험과 메시지를 설계하고 제작물을 평가·개선합니다.',prep:'관찰·구성·글쓰기, 디자인 도구, 기술 이해, 저작권',task:'불편한 서비스 화면을 개선하거나 짧은 콘텐츠 제작 후 피드백',risk:'일반적인 제작 업무는 자동화 압력을 받습니다. 도구보다 기획·사용자 이해·완성도를 쌓으세요.'},
{id:'business',name:'비즈니스·금융·제품',icon:'07',flow:'AI가 자료·거래·추천을 지원하며 고객과 조직의 일하는 방식이 바뀝니다.',life:'쇼핑·금융·계약·고객 지원의 개인화',subjects:['사회·경제','수학','국어','영어'],activities:['설명하기','사람 이해','분석하기'],majors:'경영·경제·산업공학·통계',jobs:['제품·서비스 기획자','사업·운영 분석가','기술영업·솔루션 전문가'],work:'고객의 요구와 비용·데이터·기술을 연결해 제품과 운영을 개선합니다.',prep:'경제·통계, 스프레드시트, 발표·협상, 기술 기초',task:'사용자 3명의 요구를 조사해 제품·서비스 제안 작성',risk:'단순 보고서·자료 정리는 자동화됩니다. 실제 고객·운영 문제를 이해하세요.'},
{id:'education',name:'교육·돌봄·사람 지원',icon:'08',flow:'AI의 개인화 지원과 사람의 관계·지도 역할이 함께 바뀔 수 있습니다.',life:'학습·재교육·돌봄 서비스 방식 변화',subjects:['국어','사회·경제','생명과학','영어'],activities:['사람 돕기','설명하기','사람 이해'],majors:'교육·심리·사회복지·간호·보건 등',jobs:['교사·교육 전문가','학습 콘텐츠·교육 서비스 기획자','돌봄·복지 전문직'],work:'사람의 상황을 이해하고 학습·생활 지원을 설계하거나 전문 자격에 따라 제공합니다.',prep:'읽기·설명·경청, 발달·사회 이해, 데이터와 AI 활용',task:'개념을 친구에게 설명하고 이해 여부에 따라 자료 개선',risk:'사람을 돕는 직업도 업무가 바뀝니다. 직종별 자격·정서적 부담·근무환경을 확인하세요.'},
{id:'city',name:'도시·건축·이동·물류',icon:'09',flow:'센서·시뮬레이션·자동화가 공간과 이동 시스템의 설계·운영에 연결됩니다.',life:'교통·배송·건물·도시 운영 방식 변화',subjects:['수학','물리','지구과학','사회·경제','미술·디자인'],activities:['만들기','분석하기','사회 문제 해결'],majors:'건축·도시·교통·토목·물류·산업공학',jobs:['공간·인프라 설계 전문가','교통·물류 분석가','시설·스마트빌딩 운영 전문가'],work:'공간·흐름·시설을 설계하고 비용·안전·사용 편의를 조정합니다.',prep:'기하·물리, 지도·데이터 읽기, 설계·경제·안전',task:'통학 동선이나 공간의 불편을 관찰해 개선안 작성',risk:'일부 직무는 현장·법정 자격과 관련됩니다. 설계 자동화와 산업 경기 영향도 고려하세요.'},
{id:'food',name:'식량·농업·새로운 제조',icon:'10',flow:'센서·자동화·바이오 기술이 생산·품질·자원 사용을 바꿀 수 있습니다.',life:'먹거리 생산·유통·품질 관리·제조 과정 변화',subjects:['생명과학','화학','물리','수학'],activities:['연구하기','손으로 실습','문제 해결'],majors:'식품·농생명·기계·산업·화학공학',jobs:['식품·생산 공정 전문가','스마트농업·장비 전문가','제조 품질·자동화 엔지니어'],work:'생산 조건·장비·품질 데이터를 분석하고 안전과 효율을 개선합니다.',prep:'생명·화학·물리, 실험·통계, 공정·장비 이해',task:'식품 표시·생산 과정을 조사하거나 안전한 생장 관찰',risk:'현장 조건·안전·원가·지역에 따라 업무가 다릅니다. 실험과 실제 생산의 차이를 살펴보세요.'}
];
const chosenSubjects=new Set(),chosenActivities=new Set();let route='flow',activeDomain=null;
titles.explore=['EXPLORE YOUR FUTURE','미래와 나의 관심을 연결하기','미래 변화에서 시작하거나, 좋아하는 과목·활동에서 시작하세요.'];
titles.career=['FIELDS & CAREERS','미래 분야별 직업과 준비','넓은 직업군에서 실제 업무·전공·학습·주의점을 함께 확인합니다.'];
const subjectOptions=['수학','물리','화학','생명과학','지구과학','정보','국어','영어','사회·경제','미술·디자인'];
const activityOptions=['만들기','분석하기','문제 해결','손으로 실습','연구하기','사람 돕기','설명하기','사람 이해','표현하기','사회 문제 해결'];
function domainDetails(d){return `<article class="card section" id="domain-detail"><div class="detail-heading"><span class="domain-icon">${appIcon(domainIcons[d.id])}</span><span class="tag">관심 분야 탐구</span><button class="detail-close" data-domain="${d.id}" aria-label="${d.name} 상세 닫기">닫기</button></div><h2>${d.name}</h2><p>${d.flow}</p><div class="grid"><div><h3>생활에서 달라질 부분</h3><p>${d.life}</p><h3>연결할 직업군</h3><ul class="list">${d.jobs.map(j=>`<li>${j}</li>`).join('')}</ul><h3>실제 하는 일</h3><p>${d.work}</p></div><div><h3>관련 대학 학과</h3><p>${d.majors}</p><h3>연결되는 학교 과목</h3><div class="subject-tags">${d.subjects.map(s=>`<span>${s}</span>`).join('')}</div><h3>공부와 준비</h3><p>${d.prep}</p><h3>먼저 해볼 활동</h3><p>${d.task}</p></div></div><div class="requirements"><strong>장기적으로 점검할 부분</strong><br>${d.risk}</div><p class="mini">같은 직업군 안에서도 역할·기업·자격에 따라 준비가 다릅니다. AI가 만든 새 직업명이나 취업 보장 목록이 아닙니다.</p></article>`}
function openDomainButtons(ds,reasons=false){return `<div class="grid">${ds.map(d=>{const subs=d.subjects.filter(s=>chosenSubjects.has(s)),acts=d.activities.filter(a=>chosenActivities.has(a));return `<article class="card domain-card" data-field="${d.id}"><div class="domain-card-top"><span class="domain-icon">${appIcon(domainIcons[d.id])}</span><span class="domain-kicker">미래 분야 ${d.icon}</span></div><h3>${d.name}</h3><p>${d.flow}</p>${reasons?`<div class="requirements"><strong>선택과 연결되는 이유</strong><br>${subs.length?'과목: '+subs.join(' · '):''}${subs.length&&acts.length?'<br>':''}${acts.length?'활동: '+acts.join(' · '):''}</div>`:''}<button class="jobbutton" data-domain="${d.id}" aria-expanded="${activeDomain===d.id}">${activeDomain===d.id?'상세 닫기':'직업과 공부 살펴보기'}</button></article>`}).join('')}</div>${ds.some(d=>d.id===activeDomain)?domainDetails(ds.find(d=>d.id===activeDomain)):''}`}
function exploring(){const buttons=(items,set,key)=>items.map(v=>`<button data-${key}="${v}" class="${set.has(v)?'active':''}" aria-pressed="${set.has(v)}">${v}</button>`).join('');let result='';if(route==='self'){const n=chosenSubjects.size+chosenActivities.size;const ranked=domains.map((d,i)=>({d,i,m:d.subjects.filter(s=>chosenSubjects.has(s)).length+d.activities.filter(a=>chosenActivities.has(a)).length})).filter(v=>v.m>0).sort((a,b)=>b.m-a.m||a.i-b.i);result=`<section class="section"><h2>1. 좋아하거나 더 배우고 싶은 과목</h2><div class="filter">${buttons(subjectOptions,chosenSubjects,'subject')}</div><h2>2. 해보고 싶은 활동</h2><div class="filter">${buttons(activityOptions,chosenActivities,'activity')}</div><p class="mini">복수 선택 가능 · 잘하는 과목과 좋아하는 과목은 다를 수 있습니다.</p></section><section class="section"><h2>${n?'선택한 관심과 연결되는 분야':'과목이나 활동을 선택해 보세요'}</h2><div class="note">추천은 분야별 과목·활동 목록과 겹치는 항목을 비교합니다. 겹침이 많은 순서이며 동점은 기본 순서입니다. 적성·성공 확률·취업 가능성을 계산하지 않습니다. 선택하지 않은 분야도 탐색할 수 있습니다.</div>${n?openDomainButtons(ranked.map(x=>x.d),true):'<div class="callout">아직 모르면 활동부터 선택해도 됩니다. 관심은 경험하면서 달라질 수 있습니다.</div>'}</section>`}else result=`<div class="callout"><strong>미래의 변화 → 관심 분야 → 직업 → 공부와 체험</strong><br>궁금한 분야를 열고 실제 업무와 준비를 확인하세요. 변화의 속도는 산업·비용·정책에 따라 달라집니다.</div><section class="section">${openDomainButtons(domains)}</section>`;return `<div class="tabs" role="group" aria-label="탐색 시작점"><button data-route="flow" class="${route==='flow'?'active':''}" aria-pressed="${route==='flow'}">미래 변화에서 찾기</button><button data-route="self" class="${route==='self'?'active':''}" aria-pressed="${route==='self'}">좋아하는 과목·활동에서 찾기</button></div>${result}<section class="section"><h2>관심과 적성을 확인하는 방법</h2><p class="mini">분야 하나를 선택해 작은 활동을 해본 뒤 재미·학습 부담·재도전 의지를 기록하세요. 전공은 성적·과목 선택·교육과정·비용까지 함께 검토합니다.</p><button class="jobbutton" data-page="plan">12주 준비계획 보기</button></section>`}
careers=function(){return `<div class="note">특정 기기나 산업에 한정하지 않습니다. 각 분야의 직업은 예시이며, 미래 수요의 확정 순위가 아닙니다. 의료·교육·설계 등 자격이 필요한 직종은 별도 경로를 확인해야 합니다.</div>${openDomainButtons(domains)}<section class="section"><h2>30년을 위한 경력의 세 경로</h2><div class="grid three">${card('기술','깊은 전문성','실무 → 분야 전문가 → 수석 전문가·교육·자문')}${card('조직','협업과 사업 책임','실무 → 프로젝트·팀 책임 → 개발·사업 책임')}${card('독립','경험을 서비스로 확장','실무 경험 → 전문 서비스·교육·자문·창업')}</div><p class="mini">가능한 경로의 예시입니다. 승진·창업 성과를 보장하지 않습니다. 새로운 기술과 시장 변화를 계속 점검하세요.</p></section>`};
const originalPlanning=planning;planning=function(){return originalPlanning().replace('휴대폰 3종 비교','관심 분야의 제품·서비스 3종 비교').replace('공식 사양·가격·사용 목적을 비교하고 출처를 표시합니다.','공식 자료·가격·사용 목적을 비교하고 출처를 표시합니다.').replace('기존 기기에서 조건 1개만 바꿔 배터리 소모 등을 반복 측정합니다.','관심 분야에서 안전한 측정·관찰을 설계하고 조건·반복·한계를 기록합니다.').replace('단축어·루틴·간단한 코드로 불편 1개를 해결합니다.','자동화·설명자료·모형 등으로 관심 분야의 불편 1개를 해결합니다.').replace('작동하는 기능 1개','문제해결 결과물 1개').replace('측정 보고서 1개','관찰·분석 보고서 1개').replace('사용자별 추천안 1개','사용자 의견 반영안 1개')};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let changed=false;if(b.dataset.route){route=b.dataset.route;activeDomain=null;changed=true}for(const [key,set]of [['subject',chosenSubjects],['activity',chosenActivities]])if(b.dataset[key]){const v=b.dataset[key];set.has(v)?set.delete(v):set.add(v);activeDomain=null;changed=true}if(b.dataset.domain){activeDomain=activeDomain===b.dataset.domain?null:b.dataset.domain;changed=true}if(changed){const pos=window.scrollY;render();window.scrollTo(0,pos)}});
page='explore';
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'configure_interest_exploration',title:'관심 탐색 구성',description:'선택한 과목과 활동을 화면에 반영하고 연결 분야를 보여줍니다. 적성검사 결과는 아닙니다.',inputSchema:{type:'object',properties:{subjects:{type:'array',items:{type:'string',enum:subjectOptions}},activities:{type:'array',items:{type:'string',enum:activityOptions}}},required:['subjects','activities'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>!['subjects','activities'].includes(k))||!Array.isArray(input.subjects)||!Array.isArray(input.activities)||input.subjects.some(v=>!subjectOptions.includes(v))||input.activities.some(v=>!activityOptions.includes(v)))throw new Error('지원되는 과목·활동 배열을 입력하세요.');chosenSubjects.clear();chosenActivities.clear();input.subjects.forEach(v=>chosenSubjects.add(v));input.activities.forEach(v=>chosenActivities.add(v));page='explore';route='self';activeDomain=null;render();return {subjects:[...chosenSubjects],activities:[...chosenActivities],relatedFields:domains.filter(d=>d.subjects.some(s=>chosenSubjects.has(s))||d.activities.some(a=>chosenActivities.has(a))).map(d=>d.name)}}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
